// Generated by Suite Builder from a crawl of the site. Where the site under test lives, and the values tests must not hard-code.
// EDIT RULES: edit only inside YOURS blocks; regenerating keeps them and rewrites the rest of this file.
/**
 * The site under test. Defaults to the crawled site; point the suite elsewhere (a staging copy,
 * say) with BASE_URL=https://staging.example.com (cypress.config.ts reads it) or
 * npx cypress run --config baseUrl=https://staging.example.com.
 */
export const SiteConfig = {
  CRAWLED_URL: 'https://the-internet.herokuapp.com',

  baseUrl(): string {
    const url = Cypress.config('baseUrl') ?? SiteConfig.CRAWLED_URL;
    return url.endsWith('/') ? url.slice(0, -1) : url;
  },

  /** The full URL of a path on the site under test, e.g. url('/about'). */
  url(path: string): string {
    return SiteConfig.baseUrl() + (path.startsWith('/') ? path : `/${path}`);
  },

  /**
   * A secret a test needs (a password, an API key), from the environment variable CYPRESS_<name>
   * (or --env name=...), as a Cypress chain: SiteConfig.secret('password').then((password) =>
   * UserActions.typeSecret(LoginElements.PASSWORD_INPUT, password)). Fails, saying how to pass it,
   * when it isn't set. Secrets never go into the code, a saved page or a log.
   */
  secret(name: string): Cypress.Chainable<string> {
    return cy.env([name], { log: false }).then((values) => {
      const value = values[name] as unknown;
      if (value === undefined || value === null || value === '') {
        throw new Error(`This test needs ${name}: set the CYPRESS_${name} environment variable (or --env ${name}=...). Never write it into the code.`);
      }
      return String(value);
    });
  },

  /**
   * Test data that may differ between copies of the site (a product on staging): from
   * --expose name=... (or the expose block of cypress.config.ts), else the fallback.
   */
  value(name: string, fallback: string): string {
    const value = Cypress.expose(name) as unknown;
    return value === undefined || value === null || value === '' ? fallback : String(value);
  },

  // ==== YOURS (extras): safe to edit; regenerating keeps what is between these lines ====
  // More settings the suite needs, e.g.:
  // searchTerm(): string {
  //   return SiteConfig.value('searchTerm', 'cloud');
  // },
  // ==== END YOURS (extras) ====
};
